import AVFoundation
import AudioToolbox

/// A clip window's isolated voice rendered offline into a file (spec §11
/// AU-51), S2's recipe: Apple's `AUSoundIsolation` (`aufx`/`vois`/`appl`)
/// with the High Quality Voice model (parameter 1 = 0) at 100 % wet
/// (parameter 0 = 100), each channel through its own engine in
/// `AVAudioEngine`'s offline manual rendering at 48 kHz mono, the engines in
/// lockstep over ONE `RampSourceReader`.
///
/// The model adapts over 0.5–2 s and silence resets it, so 4 s of the media
/// is fed before the window (from frame 0 when the window starts sooner),
/// then the media to the window's end and zeros past it until the window's
/// last frame is out. The unit's latency is a constant 4440 frames at
/// 48 kHz; a unit that reports anything else fails the render rather than
/// writing a misaligned file. The first preroll + 4440 output frames are
/// discarded, so kept frame 0 is the window's first frame.
///
/// Blocking, on the caller's queue: `RampAudioRenders` renders into
/// `cache/isolated/`, named by `IsolationCache`. Windows starting mid-file
/// differ from a whole-file render by about −51 dB (S2), so a render is never
/// checked by rendering it again.
enum IsolationRenderer {
    /// Part of the cache key (AU-52): bump it whenever the written file changes.
    static let version = 1
    static let sampleRate = 48_000
    /// The unit's latency at 48 kHz mono (S2), discarded and pinned.
    static let latencyFrames = 4440
    /// 4 s of media fed before the window.
    static let prerollFrames: Int64 = 192_000
    static let maxFrames: AVAudioFrameCount = 4096

    struct Job {
        /// 48 kHz with no MP3 trim (`RampAudioCache.renderSource`'s copy, or
        /// a reversed file).
        let source: URL
        let window: IsolationWindow
        /// A `.caf`; written as "<destination>.partial", then renamed.
        let destination: URL
    }

    struct Report: Equatable {
        /// The window's length.
        let frames: Int64
        /// The source's, clamped 1…2.
        let channels: Int
        /// The unit's reported latency, discarded.
        let latencyFrames: Int
        let wallSeconds: Double
    }

    enum RenderError: LocalizedError, Equatable {
        case unreadable(String), failed(String), cancelled

        var errorDescription: String? {
            switch self {
            case .unreadable(let why): return "The isolated voice's source cannot be read: \(why)."
            case .failed(let why): return "The isolated voice could not be rendered: \(why)."
            case .cancelled: return "The isolated voice's render was cancelled."
            }
        }
    }

    /// One channel's feed: frame after frame of channel `channel` from
    /// `next`, the media inside the window's end and zeros past it.
    private final class Feeder: @unchecked Sendable {
        let source: RampSourceReader
        let channel: Int
        let end: Int64
        private(set) var next: Int64
        private(set) var error: Error?

        init(source: RampSourceReader, channel: Int, from start: Int64, end: Int64) {
            self.source = source
            self.channel = channel
            self.end = end
            next = start
        }

        func feed(_ count: Int, into list: UnsafeMutablePointer<AudioBufferList>) {
            do {
                try source.fill(through: min(next + Int64(count), end))
            } catch {
                self.error = error
            }
            for buffer in UnsafeMutableAudioBufferListPointer(list) {
                guard let data = buffer.mData?.assumingMemoryBound(to: Float.self) else {
                    continue
                }
                for i in 0..<count {
                    let k = next + Int64(i)
                    data[i] = k < end ? source.sample(k, channel: channel) : 0
                }
            }
            next += Int64(count)
        }
    }

    /// One channel's engine: its feeder → the unit → the main mixer.
    private struct Lane {
        let engine: AVAudioEngine
        let buffer: AVAudioPCMBuffer
        let feeder: Feeder
    }

    static func render(_ job: Job, cancelled: () -> Bool) throws -> Report {
        let started = Date()
        let asset = AVURLAsset(url: job.source)
        guard let track = CompositionBuilder.firstTrack(of: asset, mediaType: .audio) else {
            throw RenderError.unreadable("\(job.source.lastPathComponent) has no audio track")
        }
        guard let signature = CompositionBuilder.audioFormatSignature(of: track) else {
            throw RenderError.unreadable(
                "\(job.source.lastPathComponent)'s audio format cannot be read")
        }
        let trim = MP3Gapless.leadingTrim(of: job.source, track: track)
        guard !AudioRateCopy.needsCopy(signature, trim: trim) else {
            throw RenderError.unreadable(
                "\(job.source.lastPathComponent) is \(Int(signature.sampleRate)) Hz"
                    + (trim > .zero ? " with an MP3 encoder delay" : "")
                    + "; only a 48 kHz source with no trim is rendered")
        }
        let window = job.window
        let frames = window.endFrame - window.firstFrame
        guard window.firstFrame >= 0, frames > 0 else {
            throw RenderError.failed(
                "the window [\(window.firstFrame), \(window.endFrame)) holds no frame")
        }
        let channels = Int(min(max(signature.channels, 1), 2))
        let preroll = min(prerollFrames, window.firstFrame)
        let feedStart = window.firstFrame - preroll
        let partial = URL(fileURLWithPath: job.destination.path + ".partial")
        try? FileManager.default.removeItem(at: partial)
        var writer: RampCAFWriter?
        do {
            let source = try RampSourceReader(
                asset: asset, track: track, channels: channels, from: feedStart)
            let lanes = try (0..<channels).map {
                try lane(
                    Feeder(source: source, channel: $0, from: feedStart, end: window.endFrame))
            }
            defer { lanes.forEach { $0.engine.stop() } }
            writer = try RampCAFWriter(url: partial, channels: channels)
            let discard = preroll + Int64(latencyFrames)
            var out = [Float](repeating: 0, count: Int(maxFrames) * channels)
            var rendered: Int64 = 0
            var written: Int64 = 0
            while written < frames {
                if cancelled() { throw RenderError.cancelled }
                var got = Int64(maxFrames)
                for lane in lanes {
                    let status: AVAudioEngineManualRenderingStatus
                    do {
                        status = try lane.engine.renderOffline(maxFrames, to: lane.buffer)
                    } catch {
                        throw RenderError.failed("renderOffline: \(error.localizedDescription)")
                    }
                    if let error = lane.feeder.error {
                        throw RenderError.failed("the source: \(error.localizedDescription)")
                    }
                    guard status == .success else {
                        throw RenderError.failed("renderOffline answered status \(status.rawValue)")
                    }
                    got = min(got, Int64(lane.buffer.frameLength))
                }
                if got == 0 { throw RenderError.failed("renderOffline rendered no frames") }
                source.drop(before: lanes.map(\.feeder.next).min() ?? feedStart)
                let from = max(0, discard - rendered)
                let upTo = min(got, discard + frames - rendered)
                if upTo > from {
                    let count = Int(upTo - from)
                    for (c, lane) in lanes.enumerated() {
                        guard let data = lane.buffer.floatChannelData?[0] else {
                            throw RenderError.failed("a render buffer had no samples")
                        }
                        for i in 0..<count { out[i * channels + c] = data[Int(from) + i] }
                    }
                    try writer!.write(out, frames: count)
                    written += Int64(count)
                }
                rendered += got
            }
            try writer!.close()
            writer = nil
            guard rename(partial.path, job.destination.path) == 0 else {
                throw RenderError.failed("the file could not be moved into place (errno \(errno))")
            }
            return Report(
                frames: frames, channels: channels, latencyFrames: latencyFrames,
                wallSeconds: Date().timeIntervalSince(started))
        } catch {
            writer?.abandon()
            try? FileManager.default.removeItem(at: partial)
            throw reworded(error)
        }
    }

    /// The reader's and the writer's errors in this renderer's words.
    private static func reworded(_ error: Error) -> RenderError {
        switch error {
        case let known as RenderError: return known
        case RampAudioRenderer.RenderError.unreadable(let why): return .unreadable(why)
        case RampAudioRenderer.RenderError.failed(let why): return .failed(why)
        case RampAudioRenderer.RenderError.cancelled: return .cancelled
        default: return .failed(error.localizedDescription)
        }
    }

    /// One mono engine with the unit set to S2's recipe, started in offline
    /// manual rendering; refuses a unit whose latency is not 4440 frames.
    private static func lane(_ feeder: Feeder) throws -> Lane {
        guard let format = AVAudioFormat(
            standardFormatWithSampleRate: Double(sampleRate), channels: 1)
        else { throw RenderError.failed("no mono float format") }
        let unit = AVAudioUnitEffect(
            audioComponentDescription: AudioComponentDescription(
                componentType: kAudioUnitType_Effect,
                componentSubType: kAudioUnitSubType_AUSoundIsolation,
                componentManufacturer: kAudioUnitManufacturer_Apple, componentFlags: 0,
                componentFlagsMask: 0))
        let model = AudioUnitSetParameter(
            unit.audioUnit, AudioUnitParameterID(kAUSoundIsolationParam_SoundToIsolate),
            kAudioUnitScope_Global, 0, 0, 0)
        let mix = AudioUnitSetParameter(
            unit.audioUnit, AudioUnitParameterID(kAUSoundIsolationParam_WetDryMixPercent),
            kAudioUnitScope_Global, 0, 100, 0)
        guard model == noErr, mix == noErr else {
            throw RenderError.failed(
                "the voice isolation unit refused its settings (\(model), \(mix))")
        }
        let node = AVAudioSourceNode(format: format) { _, _, count, list in
            feeder.feed(Int(count), into: list)
            return noErr
        }
        let engine = AVAudioEngine()
        engine.attach(node)
        engine.attach(unit)
        engine.connect(node, to: unit, format: format)
        engine.connect(unit, to: engine.mainMixerNode, format: format)
        do {
            try engine.enableManualRenderingMode(
                .offline, format: format, maximumFrameCount: maxFrames)
            try engine.start()
        } catch {
            throw RenderError.failed(
                "the voice isolation engine did not start: \(error.localizedDescription)")
        }
        let latency = Int((unit.latency * Double(sampleRate)).rounded())
        guard latency == latencyFrames else {
            engine.stop()
            throw RenderError.failed(
                "the voice isolation unit reports a latency of \(latency) frames, not "
                    + "\(latencyFrames)")
        }
        guard let buffer = AVAudioPCMBuffer(
            pcmFormat: engine.manualRenderingFormat, frameCapacity: maxFrames)
        else {
            engine.stop()
            throw RenderError.failed("no render buffer")
        }
        return Lane(engine: engine, buffer: buffer, feeder: feeder)
    }
}
import AVFoundation
import Foundation

/// Voice isolation's half of the tap (spec §11 AU-53, AU-54): a clip's
/// isolated render read into memory when the composition is built, and the
/// crossfade `out = dry + a·(wet − dry)` the tap runs BEFORE its chain.
///
/// **Real-time.** The pass reads only memory loaded at build time
/// (`AudioTap.swift`'s header; S1's rule): no file, no lock, no allocation
/// on the audio thread. A render not on disk when the composition is built
/// adds no span, so its clip plays dry until the editor rebuilds on its
/// landing.

/// One render's samples, planar 32-bit float at 48 kHz.
final class IsolatedAudio: @unchecked Sendable {
    let channels: Int
    let frames: Int
    /// One allocation per channel, freed with the object.
    private let storage: [UnsafeMutablePointer<Float>]

    /// Nil for a file that does not read whole as 48 kHz float. Read in
    /// chunks until the file's length is in: one `read(into:)` of a whole
    /// render's CAF was measured stopping 256 frames short.
    init?(contentsOf url: URL) {
        guard let file = try? AVAudioFile(
            forReading: url, commonFormat: .pcmFormatFloat32, interleaved: false),
            file.processingFormat.sampleRate == Double(IsolationRenderer.sampleRate),
            file.length > 0, file.length <= Int64(Int32.max),
            file.processingFormat.channelCount > 0
        else { return nil }
        let channels = Int(file.processingFormat.channelCount)
        let length = Int(file.length)
        let chunk: AVAudioFrameCount = 65_536
        guard let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: chunk)
        else { return nil }
        let storage = (0..<channels).map { _ -> UnsafeMutablePointer<Float> in
            let pointer = UnsafeMutablePointer<Float>.allocate(capacity: length)
            pointer.initialize(repeating: 0, count: length)
            return pointer
        }
        var filled = 0
        while filled < length {
            let ask = min(chunk, AVAudioFrameCount(length - filled))
            guard (try? file.read(into: buffer, frameCount: ask)) != nil,
                buffer.frameLength > 0, let data = buffer.floatChannelData
            else { break }
            let got = min(Int(buffer.frameLength), length - filled)
            for c in 0..<channels { (storage[c] + filled).update(from: data[c], count: got) }
            filled += got
        }
        guard filled == length else {
            storage.forEach { $0.deallocate() }
            return nil
        }
        self.channels = channels
        frames = length
        self.storage = storage
    }

    deinit { storage.forEach { $0.deallocate() } }

    func samples(channel: Int) -> UnsafePointer<Float> {
        UnsafePointer(storage[min(max(channel, 0), channels - 1)])
    }
}

/// One read per file while any composition holds it: a path maps WEAKLY to
/// its loaded render, so a render lives exactly as long as a composition's
/// tap holds it, and a rebuild that keeps it reads no file.
final class IsolatedAudioStore {
    static let shared = IsolatedAudioStore()

    private let lock = NSLock()
    private let loaded = NSMapTable<NSString, IsolatedAudio>.strongToWeakObjects()

    private init() {}

    func audio(at url: URL) -> IsolatedAudio? {
        let key = url.standardizedFileURL.path as NSString
        lock.lock()
        defer { lock.unlock() }
        if let held = loaded.object(forKey: key) { return held }
        guard let read = IsolatedAudio(contentsOf: url) else { return nil }
        loaded.setObject(read, forKey: key)
        return read
    }
}

/// One automation point's Amount at a composition input frame (spec §11
/// AU-87): the span's amount between two of these is the straight line.
struct AudioIsolationAmount: Equatable {
    let frame: Int64
    let amount: Double
}

/// One isolated segment on a composition audio track.
struct AudioIsolationSpan {
    /// Composition input frames, `[startFrame, endFrame)`.
    let startFrame: Int64
    let endFrame: Int64
    /// Wet index = frame + wetOffset (`IsolationCache.wetOffset`).
    let wetOffset: Int64
    /// The constant Amount; read only when `amounts` is empty.
    let amount: Float
    let audio: IsolatedAudio
    /// The Amount per input frame when an action moves it (AU-87): sorted,
    /// before the first the first's, after the last the last's. Empty when
    /// constant.
    var amounts: [AudioIsolationAmount] = []

    /// The Amount at input `frame`, `k` the last entry at or before it.
    fileprivate func amount(at frame: Int64, from k: Int) -> Float {
        let a = amounts[k]
        guard k + 1 < amounts.count, frame > a.frame else { return Float(a.amount) }
        let b = amounts[k + 1]
        let width = Double(b.frame - a.frame)
        guard width > 0 else { return Float(b.amount) }
        let f = min(Double(frame - a.frame) / width, 1)
        return Float(a.amount + (b.amount - a.amount) * f)
    }
    /// -1 hard left, 0 centred, +1 hard right.
    pub pan: f64,
    pub compressor: Option<Compressor>,
    /// How much background noise to remove: 0 is off, 1 the most the
    /// platform will do.
    pub noise_reduction: f64,
    /// The shape of `fade_in` and `fade_out` (format 29, spec §11 AU-114),
    /// each written only when not `linear`, so an older file's text holds.
    #[serde(skip_serializing_if = "FadeShape::is_linear")]
    pub fade_in_shape: FadeShape,
    #[serde(skip_serializing_if = "FadeShape::is_linear")]
    pub fade_out_shape: FadeShape,
    /// The clip's true-peak limiter (format version 30, spec §11 AU-21),
    /// last in the tap's chain; absent is off, and is not written.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub limiter: Option<Limiter>,
    /// How much of Apple's isolated voice replaces the clip's own sound,
    /// 0 off … 1 all of it (format 31, spec §11 AU-50), written only when
    /// not 0 so an older file's text holds. The render is Swift's, offline.
    #[serde(skip_serializing_if = "is_zero")]
    pub isolation: f64,
    /// The clip's EQ (format 32, spec §11 AU-31): named slots, so the group
    /// stays `Copy` and a patch merges per slot; absent is off.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub eq: Option<Equalizer>,
    /// The hum notch comb (format 32, spec §11 AU-33); absent is off.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub hum: Option<Hum>,
    /// Which of a stereo source's channels plays (format 32, spec §11
    /// AU-34), written only when not `both`.
    #[serde(skip_serializing_if = "AudioChannels::is_both")]
    }
}

/// The hum notch comb (spec §11 AU-33): the mains `frequency` (50 or 60
/// Hz), how deep each notch cuts in dB, and how many harmonics (1…8) it
/// takes.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Hum {
    pub frequency: i64,
    pub depth_db: f64,
    pub harmonics: i64,
}

impl Default for Hum {
    /// 60 Hz mains, 30 dB deep, four harmonics.
    fn default() -> Self {
        Hum {
            frequency: 60,
            depth_db: 30.0,
            harmonics: 4,
        }
    }
}

/// Which channels of a stereo source play (spec §11 AU-34): `left` and
/// `right` copy that channel into every channel, `swapped` exchanges them.
/// A one-channel track ignores it, as it does pan.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AudioChannels {
    #[default]
    Both,
    Left,
    Right,
    Swapped,
}

impl AudioChannels {
    pub fn is_both(&self) -> bool {
        *self == AudioChannels::Both
    }
}

/// The downward expander/gate (spec §11 AU-40, AU-43): below
/// `threshold_db` (dB relative to the clip's measured loudness, AU-41) the
/// level is pushed down by `ratio − 1` dB per dB under, never more than
/// `range_db`; `hold` keeps it open after the level falls, `attack` opens it
/// and `release` closes it. The DSP is the Swift side's.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Gate {
    /// dB re the clip's loudness: −40…0.
    pub threshold_db: f64,
    /// 1…20.
    pub ratio: f64,
    /// dB, 1…80: the most the gate takes away.
    pub range_db: f64,
    /// Ticks: 0…60 000 (100 ms).
    pub attack: Ticks,
    /// Ticks: 0…300 000 (500 ms).
    pub hold: Ticks,
    /// Ticks: 600…1 200 000 (1 ms…2 s).
    pub release: Ticks,
}

impl Default for Gate {
    /// 10 dB under the clip's loudness, 4:1, 20 dB deep, 1 ms to open, held
    /// 50 ms, 100 ms to close.
    fn default() -> Self {
        Gate {
            threshold_db: -10.0,
            ratio: 4.0,
            range_db: 20.0,
            attack: 600,
            hold: 30_000,
            release: 60_000,
        }
    }
}

/// The split-band de-esser (spec §11 AU-44, AU-45): the band above
/// `frequency` is turned down by as much as its sidechain passes
/// `threshold_db` (dB relative to the clip's loudness), never more than
/// `range_db`. The DSP is the Swift side's.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct DeEsser {
    /// Hz, 2 000…12 000: the crossover and the sidechain's cut.
    pub frequency: f64,
    /// dB re the clip's loudness: −30…+20.
    pub threshold_db: f64,
    /// dB, 1…24.
    pub range_db: f64,
}

impl Default for DeEsser {
    /// 6 kHz, at the clip's loudness, 6 dB deep.
    fn default() -> Self {
        DeEsser {
            frequency: 6_000.0,
            threshold_db: 0.0,
            range_db: 6.0,
        }
    }
}
