    /// Loudness Normalize's jobs: a clip whose chain has a stage the cache
    /// leaves out renders with no change to its settings (the run takes its
    /// limiter off for R0); any other reading stands (AU-64 (a)). Main.
    static func normalizeJobs(_ input: AudioNormalize.LoudnessInput, in document: ProjectDocument)
        -> [LoudnessMeasureRun.Job]
    {
        let snapshot = document.editedProject.snapshot
        return input.readings.map {
            LoudnessMeasureRun.Job(
                reading: $0,
                chain: ProcessedLoudness.needsRender(snapshot.clip($0.clip)?.audio)
                    ? AudioPatch() : nil)
        }
    }

    /// Runs `run` at once when nothing renders, else under the sheet, and
    /// commits `ops` of its outcome. With `refuse` (a landing's follow) each
    /// beep is that refusal instead — `empty` says why nothing was planned —
        /// before it started (G-8). Sorted by name.
        case graphicsNotCompiled([(name: String, message: String)])
        /// A graphic failed while the export drew it, at its own frame — nil
        /// when it did not compile. The export stopped and its file is gone.
        case graphicFailed(name: String, frame: Int?, message: String)
        /// A ramped clip's audio render failed (spec §11 SR-12 (g), (h)): the
        /// export waits for every ramp segment it plays and never writes one
        /// silent, so it stops, naming the clip and the renderer's reason.
        case rampAudioFailed(clip: UInt32, message: String)
        /// A clip's isolated voice (spec §11 AU-57) could not be rendered: the
        /// export waits for it as for a ramp, and stops naming the clip.
        case isolationFailed(clip: UInt32, message: String)
        /// A gated or de-essed clip's loudness was still not measured when the
        /// export's wait ran out (spec §11 AU-42): its thresholds are relative
        /// to it, so the export stops naming the clip rather than writing it
        /// ungated.
        case loudnessUnmeasured(clip: UInt32)
        /// A clip's voice effect (spec §11 AU-147) could not be rendered: the
        /// export waits for it as for its isolation, and stops naming the clip.
        case voiceFailed(clip: UInt32, message: String)
        /// A cut-out clip's person masks (spec §11 CO-6, CO-22 (e)), or a
        /// picture's foreground masks (`foreground`, CO-106), could not be made:
        /// the export waits for every mask it draws, a picture's too, and stops
        /// naming the clip rather than writing it uncut.
        case cutoutFailed(clip: UInt32, message: String, foreground: Bool = false)

        var errorDescription: String? {
            switch self {
            case .noPlan:
                return "The project could not be prepared for export."
            case .emptyTimeline:
                return "There is nothing on the timeline to export — add a clip first."
            case .presetUnavailable(let name):
                return "This Mac cannot export with the “\(name)” preset."
            case .fileTypeUnsupported(let container):
                return "“\(container)” is not a container this build can write."
            case .alphaAspectMismatch(let width, let height, let wantWidth, let wantHeight):
                return "An export that keeps transparency has to have the canvas's own shape. "
                    + "This canvas is \(width) × \(height) and \(wantWidth) × \(wantHeight) is a "
                    + "different shape, so the picture would be padded and the padding loses the "
                    + "alpha channel. Export at \(width) × \(height), at one of the sizes in the "
                    + "popup, or at any size with the same proportions."
            case .cancelled:
                return "The export was cancelled."
            case .failed(let message):
                return message
            case .graphicsNotCompiled(let refused):
                let clauses = refused.map { "the graphic \"\($0.name)\" \($0.message)" }
                return "The export was not started: " + clauses.joined(separator: "; ")
                    + ". Fix the module and export again."
            case .graphicFailed(let name, let frame?, let message):
                return "The export was stopped at frame \(frame) of the graphic \"\(name)\": "
                    + "\(message). No file was written."
            case .graphicFailed(let name, nil, let message):
                return "The export was stopped: the graphic \"\(name)\" does not compile — "
                    + "\(message). No file was written."
            case .rampAudioFailed(let clip, let message):
                return "Clip \(clip)'s retimed audio could not be rendered: \(message)."
            case .isolationFailed(let clip, let message):
                return "Clip \(clip)'s isolated voice could not be rendered: \(message)."
            case .loudnessUnmeasured(let clip):
                return "Clip \(clip)'s loudness or speech has not been measured yet, so its "
                    + "gate, leveller and de-esser cannot be set. Wait for their Status rows to "
                    + "show the clip's loudness, then export again."
            case .voiceFailed(let clip, let message):
                return "Clip \(clip)'s voice effect could not be rendered: \(message)."
            case .cutoutFailed(let clip, let message, let foreground):
                return "Clip \(clip)'s \(foreground ? "foreground" : "person") masks could not be "
                    + "made: \(message)."
            }
        }
