    "noise_reduction",
    "limiter",
    "isolation",
    "eq",
    "hum",
    "channels",
    "gate",
    "de_esser",
    "leveller",
];

/// One point of a segment's automation: the tap keys of the clip's
/// evaluated audio at `at`, in PROJECT ticks.
